-- BIT-75-01 POSTFLIGHT (solo lectura). Conforme = todas las filas 'OK'.
SELECT 'tabla de auditoria con RLS' AS chequeo, CASE WHEN (SELECT relrowsecurity FROM pg_class WHERE oid='public.usuarios_auditoria'::regclass) THEN 'OK' ELSE 'FALLA' END AS resultado
UNION ALL SELECT 'authenticated NO tiene INSERT/UPDATE/DELETE en auditoria', CASE WHEN NOT (has_table_privilege('authenticated','public.usuarios_auditoria','INSERT') OR has_table_privilege('authenticated','public.usuarios_auditoria','UPDATE') OR has_table_privilege('authenticated','public.usuarios_auditoria','DELETE')) THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'anon sin acceso a auditoria', CASE WHEN NOT has_table_privilege('anon','public.usuarios_auditoria','SELECT') THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'service_role sin UPDATE/DELETE en auditoria', CASE WHEN NOT (has_table_privilege('service_role','public.usuarios_auditoria','UPDATE') OR has_table_privilege('service_role','public.usuarios_auditoria','DELETE')) THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'trigger auditoria inmutable', CASE WHEN EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.usuarios_auditoria'::regclass AND tgname='bit75_auditoria_inmutable') THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'trigger ultimo admin en modo ALWAYS', CASE WHEN EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.perfiles'::regclass AND tgname='bit75_proteger_ultimo_admin' AND tgenabled='A') THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'trigger BIT-56-03 sigue activo', CASE WHEN EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.perfiles'::regclass AND tgname='bit56_proteger_perfiles' AND tgenabled='A') THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'bit75_listar_usuarios solo service_role', CASE WHEN has_function_privilege('service_role','public.bit75_listar_usuarios()','EXECUTE') AND NOT has_function_privilege('authenticated','public.bit75_listar_usuarios()','EXECUTE') AND NOT has_function_privilege('anon','public.bit75_listar_usuarios()','EXECUTE') THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'bit75_buscar_usuario solo service_role', CASE WHEN has_function_privilege('service_role','public.bit75_buscar_usuario(text)','EXECUTE') AND NOT has_function_privilege('authenticated','public.bit75_buscar_usuario(text)','EXECUTE') AND NOT has_function_privilege('anon','public.bit75_buscar_usuario(text)','EXECUTE') THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'perfiles/vinculos sin cambios de filas (comparar con preflight)', 'VER recuento: ' || (SELECT count(*) FROM public.perfiles)::text;
